  const invoice = r.value;
  const r2 = addLine(invoice, { sku: 'DES-HOUR', qty: 1, discountPercent: 0 });
  assert.equal(r2.ok, true);
  assert.equal(r2.value.lines[1].discountPercent, 0);
});

test('TIER_DISCOUNTS is exported from customers', () => {
  assert.ok(TIER_DISCOUNTS);
  assert.equal(TIER_DISCOUNTS.gold, 5);
  assert.equal(TIER_DISCOUNTS.silver, 2.5);
  assert.equal(TIER_DISCOUNTS.standard, 0);
});

test('lineVat calculates VAT on line amount', () => {
  const line = { qty: 1, unitPrice: 1000, vatRate: 21 };
  // Amount: 1000, VAT: 1000 * 21 / 100 = 210
  assert.equal(lineVat(line), 210);
});

test('lineVat calculates VAT after discount', () => {
  const line = { qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 21 };
  // Amount: 1000, Discount: 100, After discount: 900
  // VAT: 900 * 21 / 100 = 189
  assert.equal(lineVat(line), 189);
});

test('lineVat defaults vatRate to 0', () => {
  const line = { qty: 1, unitPrice: 1000 };
  assert.equal(lineVat(line), 0);
});

test('lineVat handles different VAT rates', () => {
  const line9 = { qty: 1, unitPrice: 1000, vatRate: 9 };
  const line21 = { qty: 1, unitPrice: 1000, vatRate: 21 };
  const line0 = { qty: 1, unitPrice: 1000, vatRate: 0 };

  assert.equal(lineVat(line9), 90);
  assert.equal(lineVat(line21), 210);
  assert.equal(lineVat(line0), 0);
});

test('lineVat rounds VAT correctly', () => {
  const line = { qty: 1, unitPrice: 1000, vatRate: 17 };
  // Amount: 1000, VAT: 1000 * 17 / 100 = 170
  assert.equal(lineVat(line), 170);
});

test('lineVat with fractional result rounds correctly', () => {
  const line = { qty: 1, unitPrice: 100, vatRate: 33 };
  // Amount: 100, VAT: 100 * 33 / 100 = 33
  assert.equal(lineVat(line), 33);
});

test('lineVat clamps to 0 (never negative)', () => {
  const line = { qty: 0, unitPrice: 1000, vatRate: 21 };
  // Line total: 0, VAT: 0 (clamped)
  assert.equal(lineVat(line), 0);
});

test('invoiceTotals with VAT calculation', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000, VAT: 1000 * 21 / 100 = 210
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.vat, 210);
  assert.equal(totals.total, 1210);
});

test('invoiceTotals with discount and VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 10, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000, Discount: 100, After discount: 900
  // VAT: 900 * 21 / 100 = 189, Total: 1000 - 100 + 189 = 1089
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 100);
  assert.equal(totals.vat, 189);
  assert.equal(totals.total, 1089);
});

test('invoiceTotals sums VAT across lines with different rates', () => {
  const invoice = {
    lines: [
      { qty: 1, unitPrice: 1000, vatRate: 21 },
      { qty: 1, unitPrice: 1000, vatRate: 9 },
      { qty: 1, unitPrice: 1000, vatRate: 0 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: 1000 * 21 / 100 = 210
  // Line 2: 1000 * 9 / 100 = 90
  // Line 3: 1000 * 0 / 100 = 0
  // Total VAT: 300
  assert.equal(totals.subtotal, 3000);
  assert.equal(totals.vat, 300);
  assert.equal(totals.total, 3300);
});

test('invoiceTotals with mixed discounts and VAT rates', () => {
  const invoice = {
    lines: [
      { qty: 2, unitPrice: 500, discountPercent: 10, vatRate: 21 },
      { qty: 1, unitPrice: 1000, discountPercent: 20, vatRate: 9 },
    ],
  };
  const totals = invoiceTotals(invoice);
  // Line 1: subtotal 1000, discount 100, after discount 900, vat 189
  // Line 2: subtotal 1000, discount 200, after discount 800, vat 72
  // Total: subtotal 2000, discount 300, vat 261, total 1961
  assert.equal(totals.subtotal, 2000);
  assert.equal(totals.discount, 300);
  assert.equal(totals.vat, 261);
  assert.equal(totals.total, 1961);
});

test('invoiceTotals clamps total to 0 even with VAT', () => {
  const invoice = {
    lines: [{ qty: 1, unitPrice: 1000, discountPercent: 100, vatRate: 21 }],
  };
  const totals = invoiceTotals(invoice);
  // Subtotal: 1000, Discount: 1000, After discount: 0, VAT: 0
  // Total: 1000 - 1000 + 0 = 0
  assert.equal(totals.subtotal, 1000);
  assert.equal(totals.discount, 1000);
  assert.equal(totals.vat, 0);
  assert.equal(totals.total, 0);
});
